      if (item.name.length <= maxLen) {
        prev.push(item);
      }
      return prev;
    }, []);
    response = dataRemove;
  }

  let data = [];
  let i = 0;
  while (i < limit) {
    data.push(response[i]);
    i++;
  }
  return data;
};

export const randomPos = (index) => {
  return Math.floor(Math.random() * index);
};
